/*Table structure for table `td_user_profile` */

DROP TABLE IF EXISTS `td_user_profile`;

CREATE TABLE `td_user_profile` (
  `id` int NOT NULL AUTO_INCREMENT,
  `profile_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `u_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `phone_no` bigint NOT NULL,
  `email_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `country_id` int NOT NULL DEFAULT '0' COMMENT 'md_countries->id',
  `state_id` int NOT NULL DEFAULT '0' COMMENT 'md_states->id',
  `city_id` int NOT NULL DEFAULT '0' COMMENT 'md_cities->id',
  `location_id` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'get result from google api',
  `latt_long` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dob` datetime DEFAULT NULL,
  `ac_for` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mother_tong` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `about_us` text COLLATE utf8mb4_general_ci,
  `religion` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gender` enum('F','M','O') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `caste_id` int DEFAULT '0',
  `oth_comm_marry_flag` enum('Y','N') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `phone_approved_flag` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `email_approved_flag` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `pay_flag` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `plan_id` int DEFAULT '0',
  `plan_act_dt` date DEFAULT NULL,
  `plan_exp_dt` date DEFAULT NULL,
  `kundali_file_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rasi_id` int DEFAULT '0',
  `nakhatra_id` int DEFAULT '0',
  `jotok_rasi_id` int DEFAULT '0',
  `file_path` text COLLATE utf8mb4_general_ci,
  `profile_verify_flag` enum('Y','N') COLLATE utf8mb4_general_ci DEFAULT 'N',
  `kyc_type` enum('A','P') COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '''A'' -> AADHAAR CARD\r\n''P'' -> PAN CARD',
  `active_flag` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `view_flag` enum('N','Y') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N' COMMENT 'N-> A/c will not show in listing Y -> a/c will be shown in listing',
  `disclaimer` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `policy` enum('Y','N') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `created_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_dt` datetime DEFAULT NULL,
  `modified_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `modified_dt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `phone_no_2` (`phone_no`,`email_id`),
  UNIQUE KEY `phone_no` (`phone_no`),
  UNIQUE KEY `email_id` (`email_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1654 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

